import React from 'react';
import PropTypes from 'prop-types';
import classNames from 'classnames';

import {
  WebexInMeeting,
  WebexMeetingControlBar,
  WebexDataProvider,
  MeetingContext
} from '@webex/components';

import styles from './styles.css';

// Custom controls to show screen share and other buttons
const meetingControls = (isActive) => (
  isActive
    ? ['mute-audio', 'mute-video', 'share-screen', 'leave-meeting']
    : ['mute-audio', 'mute-video', 'join-meeting']
);

const ActiveMeeting = ({setEscapedAuthentication, adapter, meetingId}) => {
  const meeting = adapter?.meetingsAdapter?.datasource?.meetings?.getMeetingByType('id', meetingId);

  // Patch meeting controls for API compatibility
  React.useEffect(() => {
    if (adapter?.meetingsAdapter?.meetingControls) {
      const controls = adapter.meetingsAdapter.meetingControls;
      const deviceControlMap = {
        'switch-camera': 'cameraId',
        'switch-microphone': 'microphoneId',
        'switch-speaker': 'speakerId'
      };

      Object.keys(controls).forEach((key) => {
        const control = controls[key];

        if (control && control.action && !control.patchedAction) {
          const originalAction = control.action.bind(control);
          const deviceIdField = deviceControlMap[key];

          control.action = function patchedAction(firstParam, secondParam) {
            // Device control: map deviceId to expected field
            if (deviceIdField && secondParam === undefined && typeof firstParam === 'string') {
              return originalAction({
                meetingID: meetingId,
                [deviceIdField]: firstParam
              });
            }

            // Old API: positional params to object
            if (typeof firstParam === 'string' && secondParam !== undefined) {
              return originalAction({meetingID: firstParam, ...secondParam});
            }

            // New API: pass through object
            return originalAction(firstParam);
          };
          control.patchedAction = true;
        }
      });
    }
  }, [adapter, meetingId]);

  if (!meetingId || !meeting) {
    // eslint-disable-next-line no-console
    console.warn('ActiveMeeting: Invalid meeting', {meetingId, meeting});

    return null;
  }

  return (
    <WebexDataProvider adapter={adapter}>
      <MeetingContext.Provider value={meetingId}>
        <div className={classNames(styles.callContainer, 'call-container', 'wxc-theme-light')}>
          <WebexInMeeting
            meetingID={meetingId}
            style={{flex: 1}}
            setEscapedAuthentication={setEscapedAuthentication}
          />
          <WebexMeetingControlBar
            meetingID={meetingId}
            controls={meetingControls}
          />
        </div>
      </MeetingContext.Provider>
    </WebexDataProvider>
  );
};

ActiveMeeting.propTypes = {
  setEscapedAuthentication: PropTypes.func,
  adapter: PropTypes.object.isRequired,
  meetingId: PropTypes.string.isRequired
};

ActiveMeeting.defaultProps = {
  setEscapedAuthentication: undefined
};

export default ActiveMeeting;
